"use strict";
const WB={config:null,items:[],selected:null,slot:1,ships:[],shipLimit:24,busy:false};
const $=id=>document.getElementById(id),esc=SCUI.escape;
function message(text,error=false){$('workbenchMessage').textContent=text;$('workbenchMessage').style.borderColor=error?'var(--red)':'var(--line)';}
async function action(fn){try{return await fn();}catch(e){message(e.message,true);}}
document.addEventListener('DOMContentLoaded',async()=>{
 await action(async()=>{WB.config=await SCUI.api('/api/config');SCUI.apply(WB.config.settings.appearance);const page=document.body.dataset.page;if(page==='media')await initMedia();if(page==='sources')await initSources();if(page==='stream')await initStream();});
});
async function initMedia(){
 const c=await SCUI.api('/api/catalog');WB.items=c.items;if(c.error)message(c.error,true);
 $('mediaCategory').insertAdjacentHTML('beforeend',c.categories.map(c=>`<option value="${esc(c.id)}">${esc(c.label)}</option>`).join(''));
 $('mediaSearch').oninput=renderPicker;$('mediaCategory').onchange=renderPicker;
 $('mediaItemList').onclick=e=>{const btn=e.target.closest('[data-item]');if(btn)void selectItem(btn.dataset.item);};
 $('mediaEditor').onclick=e=>{const upload=e.target.closest('[data-upload]');if(upload){WB.slot=Number(upload.dataset.upload);$('imageUpload').click();}const del=e.target.closest('[data-delete]');if(del)void action(async()=>{await SCUI.api('/api/media/delete',{id:WB.selected.id,slot:Number(del.dataset.delete)});await selectItem(WB.selected.id);message('Eigenes Bild entfernt. Vorhandene Quellenbilder bleiben gespeichert.');});if(e.target.closest('[data-refresh]'))void action(async()=>{await SCUI.api('/api/media/refresh',{id:WB.selected.id});message('Quellenprüfung für dieses Item gestartet.');});if(e.target.closest('[data-copy-folder]'))void copyText($('itemFolder').textContent);};
 $('imageUpload').onchange=async()=>{const file=$('imageUpload').files[0];if(!file||!WB.selected)return;await action(async()=>{if(file.size>12*1024*1024)throw new Error('Maximal 12 MB pro Bild.');const r=await fetch('/api/media/upload/'+encodeURIComponent(WB.selected.id)+'?slot='+WB.slot,{method:'POST',headers:{'X-SC-Request':'dashboard','Content-Type':file.type},body:file});const v=await r.json();if(!r.ok)throw new Error(v.error);await selectItem(WB.selected.id);await mediaMetrics();message('Bild gespeichert und diesem Item eindeutig zugeordnet.');});$('imageUpload').value='';};
 $('scanImages').onclick=()=>action(async()=>{await SCUI.api('/api/media/refresh',{});if(WB.selected)await selectItem(WB.selected.id);await mediaMetrics();message('Bilderordner neu eingelesen.');});
 $('prepareImages').onclick=()=>action(async()=>{const r=await SCUI.api('/api/media/prepare',{});message(r.message);await mediaMetrics();});
 renderPicker();const chosen=new URLSearchParams(location.search).get('item');await selectItem(WB.items.find(i=>i.id===chosen)?.id||WB.items[0]?.id);await mediaMetrics();
 setInterval(async()=>{if(document.hidden)return;await action(mediaMetrics);if(WB.selected){const old=WB.selected.id;const r=await SCUI.api('/api/dossier/'+old).catch(()=>null);if(r&&old===WB.selected.id&&r.revision!==WB.mediaRevision){WB.mediaRevision=r.revision;renderEditor(WB.selected,r);}}},5000);
}
function renderPicker(){const term=$('mediaSearch').value.toLocaleLowerCase('de');const cat=$('mediaCategory').value;const list=WB.items.filter(i=>(!cat||i.mainCategory===cat)&&[i.name,i.manufacturer,i.id].join(' ').toLocaleLowerCase('de').includes(term));$('mediaItemList').innerHTML=list.slice(0,120).map(i=>`<button type="button" class="picker-item ${WB.selected?.id===i.id?'is-selected':''}" data-item="${esc(i.id)}"><b>${esc(i.name)}</b><small>${esc(i.category)} / ${esc(i.subcategory)} · ${esc(i.manufacturer)}</small></button>`).join('')+(list.length>120?'<p class="settings-help">Suche verfeinern, um weitere Items zu finden.</p>':'')||'<p>Keine passenden Items.</p>';}
async function selectItem(id){if(!id)return;WB.selected=WB.items.find(i=>i.id===id);renderPicker();const item=WB.selected;const r=await SCUI.api('/api/dossier/'+encodeURIComponent(id)+'?enrich=1');if(WB.selected.id!==id)return;renderEditor(item,r);}
function renderEditor(item,result){const data=result.data||{};const own=data.ownImages||[];const folder=WB.config.settings.deployment.mediaPath.replace(/\/$/,'')+'/'+data.imageFolder;
 $('mediaEditor').innerHTML=`<div class="media-title"><div><p class="eyebrow">${esc(item.category)} / ${esc(item.subcategory)}</p><h2>${esc(item.name)}</h2><p>${esc(item.manufacturer)}${item.size?' · Größe '+esc(item.size):''}</p></div><span class="status-pill ${item.isDone?'done':'open'}">${item.isDone?'Erhalten':'Offen'}</span></div><div class="identity-code">ITEM-ID &nbsp; ${esc(item.id)}</div><div class="folder-path" id="itemFolder">${esc(folder)}</div><div class="workbench-actions"><button class="quiet-button" type="button" data-copy-folder>Ordnerpfad kopieren</button><button class="quiet-button" type="button" data-refresh>Quellen neu prüfen</button></div><div class="media-slots">${[1,2,3].map(slot=>{const img=own.find(i=>i.slot===slot);return `<article class="media-slot"><div class="media-slot-visual">${img?`<img src="${esc(img.thumbnail_url)}" alt="Eigenes Bild ${slot} für ${esc(item.name)}"/>`:'<span>+</span>'}</div><label>ANSICHT 0${slot}</label><div class="media-slot-actions"><button class="quiet-button" type="button" data-upload="${slot}">${img?'Bild ersetzen':'Bild hochladen'}</button>${img?`<button class="quiet-button" type="button" data-delete="${slot}" aria-label="Eigenes Bild ${slot} entfernen">Entfernen</button>`:''}</div></article>`;}).join('')}</div><h3>Dauerhaft gespeicherte Quellenbilder</h3><div class="media-auto">${(data.automaticImages||[]).map(i=>`<figure><img src="${esc(i.thumbnail_url)}" alt="${esc(item.name)}"/><figcaption>${esc(i.source)}<br/>${i.sourceUrl?`<a href="${esc(i.sourceUrl)}" target="_blank" rel="noopener">Originalquelle ↗</a>`:''}${i.credit?'<br/>'+esc(i.credit):''}${i.license?'<br/>'+esc(i.license):''}</figcaption></figure>`).join('')||'<p>Kein eindeutig zugeordnetes Quellenbild gespeichert.</p>'}</div>${(data.notes||[]).map(n=>'<p class="settings-help">'+esc(n)+'</p>').join('')}<p class="settings-help">${result.pending?'Quellenprüfung läuft im Hintergrund …':result.offline?'Offline-Modus · gespeicherte Bilder bleiben verfügbar.':'Eigene Bilder werden zuerst angezeigt; insgesamt maximal drei Ansichten.'}</p>`;}
async function mediaMetrics(){const s=await SCUI.api('/api/media/status');$('mediaMetrics').innerHTML=`<span><b>${WB.items.length}</b> eindeutig getrennte Items</span><span><b>${s.files}</b> lokale Bilder</span><span><b>${(s.bytes/1048576).toLocaleString('de-DE',{maximumFractionDigits:1})} MB</b> Bildspeicher</span><span><b>${s.pending+s.active}</b> Prüfungen ausstehend</span><span>${s.offline?'Offline-Modus':'Externe Quellen aktiv'}</span>`;}
const PROVIDERS=[['wiki','Star Citizen Wiki API','Item-Beschreibungen und technische Daten. Bilder werden erst nach zusätzlicher Identitätsprüfung übernommen.','https://api.star-citizen.wiki/'],['mediawiki','StarCitizen.tools','Direkter MediaWiki-Zugriff. Die UUID der Itemseite bestätigt das Bild. Mit der Wiki-API verbundene Quelle.','https://starcitizen.tools/'],['cornerstone','Cornerstone','Bezugsorte und UUID-bezogene Bilder der öffentlichen Itemseiten. Dieser Adapter hängt vom Seitenaufbau ab.','https://finder.cstone.space/']];
async function initSources(){await refreshSources();setInterval(()=>{if(!document.hidden)void action(refreshSources);},8000);$('loadShips').onclick=()=>action(async()=>{$('loadShips').disabled=true;$('shipStatus').textContent='Gespeicherte Schiffsliste wird geladen …';try{const data=await SCUI.api('/api/ships');WB.ships=data.ships||[];$('shipStatus').textContent=data.error?'Gespeicherter Stand · '+data.error:`${WB.ships.length} Schiffe · ${data.updatedAt?'Stand '+new Date(data.updatedAt).toLocaleString('de-DE'):data.frozen?'FleetYards abgeschaltet · kein gespeicherter Stand':data.offline?'Quelle deaktiviert oder offline':'Kein Datenstand'}${data.frozen&&data.updatedAt?' · FleetYards abgeschaltet, Liste wird nicht mehr aktualisiert':''}`;renderShips();}finally{$('loadShips').disabled=false;}});$('shipSearch').oninput=()=>{WB.shipLimit=24;renderShips();};$('moreShips').onclick=()=>{WB.shipLimit+=24;renderShips();};}
async function refreshSources(){const [status,catalog]=await Promise.all([SCUI.api('/api/media/status'),SCUI.api('/api/sources/catalog')]);$('sourceMetrics').innerHTML=`<span>Katalog: <b>${esc('SCMDB')}</b></span><span>Besitzstand: <b>${esc('Spiel-Log')}</b></span><span><b>${esc(catalog.items)}</b> Baupläne · <b>${esc(catalog.missionCount??'—')}</b> Aufträge</span><span>Davon <b>${esc(catalog.rewardBlueprints??'—')}</b> aus Belohnungspools · <b>${esc(catalog.retainedBlueprints??'—')}</b> erhaltene Altbestände</span><span>Spielversion: <b>${esc(catalog.version||'Unbekannt')}</b></span><span><b>${status.offline?'Offline-Modus':'Lokaler Cache aktiv'}</b></span>`;$('sourceCards').innerHTML=PROVIDERS.map(([key,name,desc,url],i)=>{const h=status.health[key],enabled=WB.config.settings.providers[key];return `<article class="surface source-card"><span class="source-number">QUELLE / 0${i+1}</span><h2>${name}</h2><p>${desc}</p><footer><span class="provider-state">${!enabled?'Deaktiviert':h?h.ok?'Zuletzt erreichbar':h.stale?'Gespeicherter Stand':'Abruf fehlgeschlagen':'Bereit · noch kein Abruf'}</span><a href="${url}" target="_blank" rel="noopener">Öffnen ↗</a></footer></article>`;}).join('');}
function renderShips(){const q=$('shipSearch').value.toLowerCase();const items=WB.ships.filter(i=>(i.name+' '+i.manufacturer).toLowerCase().includes(q));$('shipGrid').innerHTML=items.slice(0,WB.shipLimit).map(i=>{const shops=i.availability?.soldAt||[];return `<article class="ship-card"><small>${esc(i.manufacturer)}</small><h3>${esc(i.name)}</h3><p>${esc(i.focus||'Keine Einsatzrolle angegeben')}<br/>Besatzung ${esc(i.crew?.min??'—')}–${esc(i.crew?.max??'—')}</p><p>${shops.length?shops.slice(0,2).map(s=>esc(s.location)+' · '+Number(s.price).toLocaleString('de-DE')+' aUEC').join('<br/>'):'Keine Verkaufsorte hinterlegt.'}</p><a href="${esc(i.url)}" target="_blank" rel="noopener">Schiff bei FleetYards ↗</a></article>`;}).join('');$('moreShips').hidden=items.length<=WB.shipLimit;}
async function initStream(){const settings=WB.config.settings;const url=(settings.deployment.dashboardUrl||location.origin).replace(/\/$/,'')+'/obs.html';$('directObsUrl').textContent=url;$('streamResolution').textContent='Browserquelle: '+settings.obs.resolution.replace('x',' × ')+' Pixel';$('copyDirectObs').onclick=()=>copyText(url);const resize=()=>{$('streamFrame').style.transform='scale('+($('streamPreview').clientWidth/1920)+')';};new ResizeObserver(resize).observe($('streamPreview'));resize();$('previewAlert').onclick=()=>{$('streamFrame').src='/obs.html?preview=1&t='+Date.now();$('previewNote').textContent='Designvorschau mit Testdaten. Kein Eintrag in der Live-Warteschlange.';};$('testAlert').onclick=()=>action(async()=>{await SCUI.api('/api/obs/test',{});message('Testfund bereit. Die laufende OBS-Browserquelle blendet ihn ein.');await refreshStream();});$('watchLive').onclick=()=>{$('streamFrame').src='/obs.html?monitor=1';$('previewNote').textContent='Live-Beobachtung. Diese Vorschau startet keine Warteschlange; die OBS-Browserquelle übernimmt die Wiedergabe.';};$('clearAlerts').onclick=()=>action(async()=>{await SCUI.api('/api/obs/clear',{});message('Ausstehende und laufende Einblendungen beendet.');await refreshStream();});await refreshStream();setInterval(()=>{if(!document.hidden)void action(refreshStream);},2500);}
async function refreshStream(){const s=await SCUI.api('/api/obs/history');$('testAlert').disabled=!s.enabled;$('streamMetrics').innerHTML=`<span><b>${s.enabled?'Automatische Fundmeldungen aktiv':'Fundmeldungen pausiert'}</b></span><span><b>${s.duration} Sekunden</b> pro Gruppe</span><span><b>${s.pending}</b> in Warteschlange</span><span>${s.baselineReady?'Besitzstand eingelesen':'Wartet auf gültigen Besitzstand'}</span>`;const statuses={queued:'Wartet auf OBS',playing:'Wird eingeblendet',shown:'Angezeigt',expired:'Abgelaufen',skipped:'Übersprungen'};$('alertHistory').innerHTML=s.events.map(e=>`<article class="event-row"><time>${new Date(e.created*1000).toLocaleTimeString('de-DE')}</time><div><b>${esc(e.title||(e.items.length===1?'Neuer Bauplan':'Neue Baupläne'))}</b><small>${e.items.map(i=>esc(i.name)).join(' · ')}</small></div><small>${e.kind==='test'?'TEST · ':''}${esc(statuses[e.status]||e.status)}</small></article>`).join('')||'<p>Dein vorhandener Bestand ist die Ausgangsbasis. Neue Funde erscheinen hier automatisch.</p>';}
async function copyText(text){try{await navigator.clipboard.writeText(text);message('Kopiert.');}catch{message('Zum Kopieren den angezeigten Text markieren und Strg+C drücken.');}}
